import json,pandas as pd
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import roc_auc_score,average_precision_score
from common.feature_utils import load_data,add_window_features,metrics,output_path
df=add_window_features(load_data(),15); b=['speed_mps','accel_mps2','jerk_mps3','steering_deg','steering_rate_dps','yaw_rate_rps','front_distance_m','ttc_s','motor_current_a','battery_voltage_v']; e=[c for c in df if c.endswith('_mean_w') or c.endswith('_std_w') or c.endswith('_maxabs_w')]; f=b+e; s=int(len(df)*.7); m=RandomForestClassifier(n_estimators=250,class_weight='balanced',random_state=42,n_jobs=1,min_samples_leaf=2).fit(df.iloc[:s][f],df.iloc[:s].anomaly_label); p=m.predict_proba(df.iloc[s:][f])[:,1]; th=.35; pred=p>=th; o=df.iloc[s:][['time_s','event_type','anomaly_label']].copy(); o['anomaly_probability']=p; o['predicted_anomaly']=pred.astype(int); cp=output_path('ex240_integrated_predictions.csv'); o.to_csv(cp,index=False); sm={'features_used':len(f),'threshold':th,'roc_auc':float(roc_auc_score(df.iloc[s:].anomaly_label,p)),'average_precision':float(average_precision_score(df.iloc[s:].anomaly_label,p)),**metrics(df.iloc[s:].anomaly_label,pred)}; jp=output_path('ex240_integrated_summary.json'); jp.write_text(json.dumps(sm,indent=2)); ip=output_path('ex240_feature_importance.csv'); pd.DataFrame({'feature':f,'importance':m.feature_importances_}).sort_values('importance',ascending=False).to_csv(ip,index=False); print(sm)
